import{_ as n,C as a,o as l,c,j as e,a as r,G as o,a2 as d}from"./chunks/framework.BgSoyxN5.js";const v=JSON.parse('{"title":"Creator Partnerships | TickerForge","titleTemplate":false,"description":"Use TickerForge as a research layer in YouTube videos, Instagram and TikTok content, LinkedIn posts, newsletters, and blogs. Start with 14 days of Standard Review Access, with no publications required.","frontmatter":{"title":"Creator Partnerships | TickerForge","titleTemplate":false,"description":"Use TickerForge as a research layer in YouTube videos, Instagram and TikTok content, LinkedIn posts, newsletters, and blogs. Start with 14 days of Standard Review Access, with no publications required.","aside":false,"locale":"en","pageClass":"partners-page"},"headers":[],"relativePath":"partners/creators.md","filePath":"partners/creators.md","lastUpdated":1789293971000}'),p={name:"partners/creators.md"},u={class:"partners-wide"};function h(g,t,f,m,w,k){const s=a("PartnerPageAnalytics"),i=a("PartnerLeadForm");return l(),c("div",null,[t[0]||(t[0]=e("h1",{id:"use-tickerforge-in-your-investing-content",tabindex:"-1"},[r("Use TickerForge In Your Investing Content "),e("a",{class:"header-anchor",href:"#use-tickerforge-in-your-investing-content","aria-label":'Permalink to "Use TickerForge In Your Investing Content"'},"​")],-1)),t[1]||(t[1]=e("p",null,"You do not need to turn your channel into a TickerForge channel. Use TickerForge as one research layer inside the content your audience already watches or reads.",-1)),t[2]||(t[2]=e("p",null,"Add structured market data, stock checks, insider and fund activity, business quality, market regime, sector rotation, Smart Alerts, and portfolio risk to your existing investing content. Show a real check, explain what it adds to your research, and keep your own judgment.",-1)),t[3]||(t[3]=e("p",null,[r("Start with "),e("strong",null,"14 days of Standard Review Access"),r(", after application review. No publications required. If it fits, agree a "),e("strong",null,"Pilot with 1–2 test posts"),r(", supported by research blocks and tracked links. After a successful pilot, discuss "),e("strong",null,"Active Partner"),r(" terms: for example 2–4 posts per month, referral, paid or co-branded content.")],-1)),o(s,{offer:"creators",locale:"en"}),t[4]||(t[4]=d('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#creator-pilot" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="creator_hero">Request 14-day Review Access</a><a class="partners-button partners-button--secondary" href="#content-angles">Explore Content Angles</a></div><p class="partners-backlink"><a href="/partners">Back to all partner options</a></p><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, a trading robot, a copy-trading system, or a promise of returns.</p><h2 id="who-this-is-for" tabindex="-1">Who This Is For <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who This Is For&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>YouTube investing creators</li><li>Instagram and TikTok finance creators</li><li>LinkedIn finance writers</li><li>Newsletter authors and investing bloggers</li><li>Personal finance educators</li><li>Portfolio-focused creators</li><li>Communities discussing stocks and market context, including Telegram communities</li></ul></div><p>We look for creators who explain evidence, uncertainty, and risk. Creators whose main product is a signal group, copy-trading, claims of certain investment outcomes, or paid “buy/sell alerts” are not a fit.</p><h2 id="content-angles" tabindex="-1">Content Angles You Can Use <a class="header-anchor" href="#content-angles" aria-label="Permalink to &quot;Content Angles You Can Use {#content-angles}&quot;">​</a></h2><p>Pick one angle that fits your usual content:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Stock deep dive:</strong> use TickerForge as one data layer alongside your other research.</li><li><strong>“How I find stocks worth researching”:</strong> explain a screening workflow and what you check next.</li><li><strong>Portfolio risk review:</strong> explore concentration, sector exposure, and stress scenarios.</li><li><strong>Market regime or sector rotation segment:</strong> put a company or portfolio in broader context.</li><li><strong>Smart Alert follow-up:</strong> explain what changed and why it matters.</li><li><strong>Insider/fund activity evidence block:</strong> add ownership context and discuss its limits.</li><li><strong>Neutral tool walkthrough or review:</strong> show the workflow and give your own assessment.</li><li><strong>Data-backed carousel or Reel/TikTok script:</strong> build a short explanation around a real diagnostic.</li><li><strong>LinkedIn post or newsletter section:</strong> add a research example to a topic you already cover.</li><li><strong>Description, bio, or pinned-comment tracked link test:</strong> pair the link with a qualified content example so viewers know what they can check.</li></ul></div><h2 id="platform-examples" tabindex="-1">Platform Examples <a class="header-anchor" href="#platform-examples" aria-label="Permalink to &quot;Platform Examples&quot;">​</a></h2><p>The research can fit several containers. Telegram&#39;s generated posts are the most ready format today; creators on other platforms can use the product directly and shape the evidence into their own content.</p><div class="partners-wide"><div class="partners-format-grid"><div class="partners-format"><span>Video</span><strong>YouTube</strong><p>Mention a real check in your video, add a tracked description link, and optionally repeat it in a pinned comment.</p></div><div class="partners-format"><span>Visual stories</span><strong>Instagram</strong><p>Use a Reel, carousel, story, or bio link. A creator marketplace message follow-up can help agree the first topic.</p></div><div class="partners-format"><span>Short video</span><strong>TikTok</strong><p>Explain one diagnostic in a short video and use a profile link where available.</p></div><div class="partners-format"><span>Professional discussion</span><strong>LinkedIn</strong><p>Publish a post, article, newsletter, or founder/creator workflow post showing how the research informs your process.</p></div><div class="partners-format"><span>Written research</span><strong>Newsletters and blogs</strong><p>Add a screenshot or evidence block to an article or email section, with a tracked link to the matching website workflow.</p></div><div class="partners-format"><span>Generated posts available today</span><strong>Telegram</strong><p>Use a ready-to-post generated research post with a bot deep link. <a href="/partners/telegram-research">Explore Telegram research posts</a>.</p></div></div></div><h2 id="where-links-go" tabindex="-1">Where Links Go <a class="header-anchor" href="#where-links-go" aria-label="Permalink to &quot;Where Links Go&quot;">​</a></h2><p>For non-Telegram traffic, links usually go to the website first.</p><p><strong>Creator content → tracked website link → stock check / portfolio diagnostics / market page → optional Telegram bot or Workspace signup.</strong></p><p>Choose the destination that matches the content:</p><ul><li><a href="/stock-widget">Stock check</a></li><li><a href="/portfolio-diagnostics">Portfolio diagnostics</a></li><li><a href="/market-widget">Market context</a></li><li><a href="/partners">Partner hub</a> for an overview of the collaboration</li></ul><p>Creator-specific landing pages may be considered in the future. They are not required for the first pilot.</p><h2 id="partner-attribution" tabindex="-1">Partner Attribution <a class="header-anchor" href="#partner-attribution" aria-label="Permalink to &quot;Partner Attribution&quot;">​</a></h2><p>Approved creators receive a tracked partner link with <strong>a partner/referral code for attribution</strong> and <strong>UTM parameters for analytics</strong>. UTMs alone do not identify a referral owner.</p><p>For example, replace the placeholder code and campaign with the values agreed for your pilot:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://ticker-forge.com/portfolio-diagnostics?ref=creator_code&amp;utm_source=youtube&amp;utm_medium=creator&amp;utm_campaign=creator_slug&amp;utm_content=portfolio_review</span></span></code></pre></div><p>Visitors who sign up, start the bot, or become paying users through an approved creator link <strong>can be attributed when the tracked link is preserved through signup or bot start</strong>, under the existing <a href="/ambassador">Ambassador/referral rules</a>.</p><p>The website keeps the first creator code in that browser and carries it into supported email/Workspace signup and tracked Telegram handoffs. An existing first-touch referrer is not replaced. Browser storage, link preservation, and a successful handoff matter; attribution is not guaranteed across browsers or devices.</p><p>Email/Workspace leads retain the creator attribution in CRM. Referral rewards use the existing Ambassador identity and eligibility rules when the visitor connects to an eligible Telegram user account. A website visit or an email signup alone does not establish a reward.</p><h2 id="what-you-get" tabindex="-1">What You Get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What You Get&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Standard access for the creator pilot:</strong> start with 14 days of Review Access, with no publications required. If you continue to a Pilot, we agree its access dates separately.</li><li><strong>A tracked partner link:</strong> use it on the website, in a description, bio, story, pinned comment, or newsletter.</li><li><strong>Optional topic support:</strong> data screenshots or research blocks for one pilot topic, agreed with you.</li><li><strong>Referral rewards:</strong> under the existing <a href="/ambassador">Ambassador rules</a>, where applicable.</li><li><strong>Your own assessment:</strong> no obligation to endorse the tool before testing it.</li><li><strong>A simple start:</strong> no need to build an integration before the first pilot.</li></ul></div><p>“Creator pilot” describes the collaboration; access uses the existing Standard partner access. It is not a separate subscription tier.</p><h2 id="what-we-ask-in-return" tabindex="-1">What We Ask In Return <a class="header-anchor" href="#what-we-ask-in-return" aria-label="Permalink to &quot;What We Ask In Return&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>No publications during Review Access are required. If you continue, agree 1–2 qualified content tests for the Pilot.</li><li>Keep your own voice and opinion.</li><li>Use a real TickerForge check, screenshot, diagnostic, or workflow.</li><li>Include the tracked link where the platform allows it.</li><li>Use educational context and sponsored/affiliate or complimentary-access disclosures where required.</li><li>Avoid promises of returns, personalized advice, and “buy/sell signal” framing.</li></ul></div><p>The same <a href="/partners/requirements">three-stage partner requirements</a> apply to creators. We agree the content format and Pilot timing individually.</p><h2 id="pilot-flow" tabindex="-1">Pilot Flow <a class="header-anchor" href="#pilot-flow" aria-label="Permalink to &quot;Pilot Flow&quot;">​</a></h2><ol><li>Apply below or reply to our outreach, then confirm your contact.</li><li>We review your channel and topic fit.</li><li>Review Access: explore Standard for 14 days, with no publications required.</li><li>If it fits, agree a Pilot with 1–2 test posts; we provide a research block and tracked links.</li><li>Publish in your own voice and review results with us.</li><li>After a successful Pilot, discuss Active Partner terms: regular content, referral, paid or co-branded collaboration.</li></ol><h2 id="creator-pilot" tabindex="-1">Request 14-day Review Access <a class="header-anchor" href="#creator-pilot" aria-label="Permalink to &quot;Request 14-day Review Access {#creator-pilot}&quot;">​</a></h2><p>Tell us your channel, audience size, platform, average views/reach, language, and the first content angle you want to test.</p><p>Use the message field for average views/reach and your first content angle. Choose the research topic closest to your idea; no generated-post delivery format is required.</p>',36)),e("div",u,[o(i,{source:"partners_creators"})]),t[5]||(t[5]=e("ul",null,[e("li",null,[e("a",{href:"/partners"},"All partner options")]),e("li",null,[e("a",{href:"/partners/what-you-get"},"Partner benefits")]),e("li",null,[e("a",{href:"/ambassador"},"Ambassador / referral program")])],-1))])}const y=n(p,[["render",h]]);export{v as __pageData,y as default};
